cuda_source = r'''
#include <cuda_fp16.h>
#include <torch/extension.h>

template <typename scalar_t>
__global__ void maxpool1d_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int N,
    const int C,
    const int L,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation,
    const int L_out)
{
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C * L_out;
    if (idx >= total) return;

    // Decompose linear index
    const int n = idx / (C * L_out);
    const int tmp = idx % (C * L_out);
    const int c = tmp / L_out;
    const int o = tmp % L_out;

    const int input_offset = (n * C + c) * L;
    const int output_offset = (n * C + c) * L_out + o;

    const int start = o * stride - padding;
    const int end = start + (kernel_size - 1) * dilation;

    float best = -1e20f;  // -inf for fp16
    #pragma unroll
    for (int k = 0; k < kernel_size; ++k) {
        int pos = start + k * dilation;
        if (pos >= 0 && pos < L) {
            float val = __half2float(input[input_offset + pos]);
            if (val > best) best = val;
        }
    }
    output[output_offset] = __float2half(best);
}

at::Tensor maxpool1d_forward(
    const at::Tensor& input,
    const int64_t kernel_size,
    const int64_t stride,
    const int64_t padding,
    const int64_t dilation)
{
    TORCH_CHECK(input.dim() == 3, "Input must be 3D (N, C, L)");
    TORCH_CHECK(input.dtype() == at::kHalf, "Input must be float16");
    const int N = input.size(0);
    const int C = input.size(1);
    const int L = input.size(2);

    const int64_t L_out = (L + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    TORCH_CHECK(L_out > 0, "Calculated output length is non‑positive");

    auto output = at::empty({N, C, L_out}, input.options());

    const int threads = 256;
    const int blocks = (N * C * L_out + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "maxpool1d_forward", ([&] {
        maxpool1d_kernel<scalar_t><<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            N, C, L,
            static_cast<int>(kernel_size),
            static_cast<int>(stride),
            static_cast<int>(padding),
            static_cast<int>(dilation),
            static_cast<int>(L_out));
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel failed: ") + cudaGetErrorString(err));
    }

    return output;
}
'''

